import type { CategoryId, ColorId } from "./taxonomy";

/**
 * Details for each nail photo. The photo files themselves are generated by
 * `python scripts/process_images.py <folder>` and matched here by `id`
 * (the original file name, lower-cased: IMG_0010.JPG -> "img-0010").
 *
 * Categories, colors, finish and shape below are a first pass made by looking
 * at each photo. Furugh: change anything that's wrong; the gallery updates
 * itself. To change the gallery order, change `order` (lower = earlier).
 * `featured` designs get the big editorial spots.
 * `note` is an optional playful caption; it never replaces the `alt` text.
 */
export interface NailArtwork {
  id: string;
  title: string;
  alt: string;
  categories: CategoryId[];
  colors: ColorId[];
  finish?: string;
  shape?: string;
  featured: boolean;
  order: number;
  note?: string;
}

